mapper.select:
/* 1) 수동 등록 및 실체화된 일정 */ SELECT s.schedule_id AS scheduleId, m.item_name AS name, TO_CHAR(s.scheduled_at, 'HH24:MI') AS time, CASE WHEN s.prescription_id IS NOT NULL THEN 'prescription' WHEN s.routine_id IS NOT NULL THEN 'supplement' WHEN s.cabinet_id IS NOT NULL THEN 'regular' ELSE 'regular' END AS type, s.taken_at AS takenAt, NVL(s.alarm_enabled, 1) AS alarmEnabled FROM schedules s JOIN medications m ON s.medication_id = m.medication_id WHERE s.user_id = #{userId} AND TRUNC(s.scheduled_at) = TO_DATE(#{date}, 'YYYY-MM-DD')
UNION ALL
/* 2) 처방전 실시간 연동: 아직 SCHEDULES로 실체화되지 않은 처방약만 노출 */ SELECT (p.prescription_id * 1000 + pi.item_id) AS scheduleId, m.item_name AS name, '08:30' AS time, 'prescription' AS type, NULL AS takenAt, 1 AS alarmEnabled FROM prescriptions p JOIN prescription_items pi ON p.prescription_id = pi.prescription_id JOIN medications m ON pi.medication_id = m.medication_id WHERE p.user_id = #{userId}
AND TO_DATE(#{date}, 'YYYY-MM-DD') >= TRUNC(p.dispensed_date) AND TO_DATE(#{date}, 'YYYY-MM-DD') < TRUNC(p.dispensed_date) + p.total_days
AND NOT EXISTS ( SELECT 1 FROM schedules s2 WHERE s2.user_id = #{userId} AND s2.prescription_id = p.prescription_id AND s2.medication_id = pi.medication_id AND TRUNC(s2.scheduled_at) = TO_DATE(#{date}, 'YYYY-MM-DD') )
ORDER BY time ASC

WITH ALL_CALENDAR AS ( /* 수동 등록 일정 */ SELECT TO_CHAR(s.scheduled_at, 'YYYY-MM-DD') AS scheduleDate, CASE WHEN s.prescription_id IS NOT NULL THEN 1 ELSE 0 END AS hasPrescription, CASE WHEN s.prescription_id IS NULL AND s.routine_id IS NULL THEN 1 ELSE 0 END AS hasRegular, CASE WHEN s.routine_id IS NOT NULL THEN 1 ELSE 0 END AS hasSupplement FROM schedules s WHERE s.user_id = #{userId} AND TO_CHAR(s.scheduled_at, 'YYYY-MM') = #{yearMonth}
UNION ALL
/* 처방전 유효 기간 내 날짜 */ SELECT TO_CHAR(TRUNC(p.dispensed_date) + LEVEL - 1, 'YYYY-MM-DD') AS scheduleDate, 1 AS hasPrescription, 0 AS hasRegular, 0 AS hasSupplement FROM prescriptions p WHERE p.user_id = #{userId} AND TO_CHAR(TRUNC(p.dispensed_date) + LEVEL - 1, 'YYYY-MM') = #{yearMonth}
CONNECT BY LEVEL <= p.total_days AND PRIOR p.prescription_id = p.prescription_id AND PRIOR SYS_GUID() IS NOT NULL
) SELECT scheduleDate AS "scheduleDate", MAX(hasPrescription) AS "hasPrescription", MAX(hasRegular) AS "hasRegular", MAX(hasSupplement) AS "hasSupplement" FROM ALL_CALENDAR GROUP BY scheduleDate

